## Complete source file (`config/config.go`)

```go
package config

import (
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"strconv"
)

// ---------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------

// ErrInvalidConfig is returned when the config file is syntactically OK
// but fails our business‑logic validation.
var ErrInvalidConfig = errors.New("invalid configuration")

// Config holds the settings for your application.
// Add JSON tags for every key you expect in the config file.
//
// The `env:"…"` tag is *informational only* – the code below looks up the
// environment variable names manually.  You can generate the mapping
// automatically with reflection if you prefer.
type Config struct {
	Port        int    `json:"port"`          // required, 1‑65535
	DatabaseURL string `json:"database_url"` // required
	// Example of a string that may be overridden:
	LogLevel string `json:"log_level"` // optional, e.g. "info", "debug"
	// Add any other fields you need…
}

// LoadConfig reads a JSON configuration file, applies any environment‑
// variable overrides, validates the result, and returns the final Config.
//
// Errors are wrapped with context (`%w`) so callers can unwrap them.
// Validation errors are wrapped with ErrInvalidConfig, which callers can
// detect with `errors.Is(err, ErrInvalidConfig)`.
func LoadConfig(path string) (*Config, error) {
	// -------------------------------------------------------------
	// 1️⃣ Open the file (streaming – avoids loading the whole file)
	// -------------------------------------------------------------
	f, err := os.Open(path)
	if err != nil {
		return nil, fmt.Errorf("opening config file %q: %w", path, err)
	}
	defer f.Close()

	// -------------------------------------------------------------
	// 2️⃣ Decode JSON with strict field checking
	// -------------------------------------------------------------
	var cfg Config
	dec := json.NewDecoder(f)
	dec.DisallowUnknownFields()
	if err := dec.Decode(&cfg); err != nil {
		return nil, fmt.Errorf("decoding JSON from %q: %w", path, err)
	}

	// -------------------------------------------------------------
	// 3️⃣ Apply environment‑variable overrides (if any)
	// -------------------------------------------------------------
	applyEnvOverrides(&cfg)

	// -------------------------------------------------------------
	// 4️⃣ Validate required fields (custom logic)
	// -------------------------------------------------------------
	if err := validateConfig(&cfg); err != nil {
		return nil, fmt.Errorf("%w: %s", ErrInvalidConfig, err)
	}

	return &cfg, nil
}

// ---------------------------------------------------------------------
// Helper: environment variable overrides
// ---------------------------------------------------------------------

// applyEnvOverrides checks known environment variables and, when they
// are set, overwrites the corresponding fields in the Config struct.
//
// The mapping is explicit so the code stays easy to read and type‑safe.
// Add new entries here when you add new Config fields that you want
// to be overridable.
func applyEnvOverrides(cfg *Config) {
	// ----- PORT (int) -------------------------------------------------
	if v, ok := os.LookupEnv("APP_PORT"); ok {
		if i, err := strconv.Atoi(v); err == nil {
			cfg.Port = i
		}
		// If conversion fails we simply ignore the env var – the
		// validation step later will surface the problem.
	}

	// ----- DATABASE_URL (string) --------------------------------------
	if v, ok := os.LookupEnv("APP_DATABASE_URL"); ok {
		cfg.DatabaseURL = v
	}

	// ----- LOG_LEVEL (string) -----------------------------------------
	if v, ok := os.LookupEnv("APP_LOG_LEVEL"); ok {
		cfg.LogLevel = v
	}

	// Add more overrides here, following the same pattern:
	//   if v, ok := os.LookupEnv("ENV_VAR_NAME"); ok { cfg.SomeField = v }
}

// ---------------------------------------------------------------------
// Validation helper (private)
// ---------------------------------------------------------------------

func validateConfig(c *Config) error {
	if c.Port <= 0 || c.Port > 65535 {
		return fmt.Errorf("port must be between 1 and 65535 (got %d)", c.Port)
	}
	if c.DatabaseURL == "" {
		return errors.New("database_url is required")
	}
	// Example validation for log level – optional
	if c.LogLevel != "" {
		switch c.LogLevel {
		case "debug", "info", "warn", "error":
			// ok
		default:
			return fmt.Errorf("log_level must be one of debug|info|warn|error (got %q)", c.LogLevel)
		}
	}
	// Add any further domain‑specific checks here.
	return nil
}
```

