package config

import (
	"encoding/json"
	"os"
	"path/filepath"
	"strconv"
	"testing"
)

// helper – write a JSON file in a temporary directory and return its path.
func writeTempJSON(t *testing.T, data interface{}) string {
	t.Helper()

	dir := t.TempDir()
	path := filepath.Join(dir, "cfg.json")

	f, err := os.Create(path)
	if err != nil {
		t.Fatalf("cannot create temp file: %v", err)
	}
	enc := json.NewEncoder(f)
	enc.SetIndent("", "  ")
	if err := enc.Encode(data); err != nil {
		t.Fatalf("cannot write json: %v", err)
	}
	if err := f.Close(); err != nil {
		t.Fatalf("cannot close temp file: %v", err)
	}
	return path
}

// helper – set an env var for the duration of a sub‑test and restore the old value.
func withEnv(key, value string, fn func()) {
	orig, had := os.LookupEnv(key)
	os.Setenv(key, value)
	defer func() {
		if had {
			os.Setenv(key, orig)
		} else {
			os.Unsetenv(key)
		}
	}()
	fn()
}

func TestLoadConfig(t *testing.T) {
	// Define a “baseline” config that is valid on its own.
	baseCfg := Config{
		Port:        1234,
		DatabaseURL: "postgres://user:pw@localhost/db",
		LogLevel:    "info",
	}

	tests := []struct {
		name          string
		jsonCfg       Config               // what to write to the file
		envOverrides  map[string]string    // env var → value (nil means “unset”)
		want          Config               // expected final struct after overrides
		wantErr       bool                 // any error expected?
		wantErrIs     error                // specific sentinel to check with errors.Is (optional)
		validateErr   string               // if validation fails, the exact message (optional)
	}{
		{
			name:    "happy‑path – no overrides",
			jsonCfg: baseCfg,
			want:    baseCfg,
		},
		{
			name:    "override port via env",
			jsonCfg: baseCfg,
			envOverrides: map[string]string{
				"APP_PORT": "8080",
			},
			want: Config{
				Port:        8080,
				DatabaseURL: baseCfg.DatabaseURL,
				LogLevel:    baseCfg.LogLevel,
			},
		},
		{
			name:    "override several fields",
			jsonCfg: baseCfg,
			envOverrides: map[string]string{
				"APP_PORT":          "9000",
				"APP_DATABASE_URL": "postgres://new:pw@host/db2",
				"APP_LOG_LEVEL":    "debug",
			},
			want: Config{
				Port:        9000,
				DatabaseURL: "postgres://new:pw@host/db2",
				LogLevel:    "debug",
			},
		},
		{
			name:    "invalid JSON syntax",
			jsonCfg: Config{}, // we will write a malformed file manually
			envOverrides: map[string]string{
				// no env vars – they don’t matter here
			},
			wantErr: true, // json.Decoder will report an error
		},
		{
			name:    "missing required field (DatabaseURL)",
			jsonCfg: Config{Port: 1234, LogLevel: "info"},
			wantErr: true,
			wantErrIs: ErrInvalidConfig,
			validateErr: "database_url is required",
		},
		{
			name:    "port out of range (validation)",
			jsonCfg: Config{Port: 70000, DatabaseURL: "postgres://x", LogLevel: "info"},
			wantErr: true,
			wantErrIs: ErrInvalidConfig,
			validateErr: "port must be between 1 and 65535",
		},
		{
			name:    "env var non‑numeric for port – keep original (validation will catch later)",
			jsonCfg: baseCfg,
			envOverrides: map[string]string{
				"APP_PORT": "not-a-number",
			},
			// The conversion fails, so the original port (1234) stays.
			want: baseCfg,
		},
		{
			name:    "env var overrides invalid log level – validation error",
			jsonCfg: baseCfg,
			envOverrides: map[string]string{
				"APP_LOG_LEVEL": "unknown",
			},
			wantErr: true,
			wantErrIs: ErrInvalidConfig,
			validateErr: `log_level must be one of debug|info|warn|error`,
		},
	}

	for _, tt := range tests {
		tt := tt // capture range variable
		t.Run(tt.name, func(t *testing.T) {
			// -------------------------------------------------
			// 1️⃣ Prepare the JSON file (or malformed content)
			// -------------------------------------------------
			var cfgPath string
			if tt.name == "invalid JSON syntax" {
				// Write a deliberately broken JSON file
				dir := t.TempDir()
				cfgPath = filepath.Join(dir, "bad.json")
				if err := os.WriteFile(cfgPath, []byte("{invalid json"), 0o600); err != nil {
					t.Fatalf("cannot write malformed json file: %v", err)
				}
			} else {
				cfgPath = writeTempJSON(t, tt.jsonCfg)
			}

			// -------------------------------------------------
			// 2️⃣ Set the environment variables for this sub‑test
			// -------------------------------------------------
			// Save the current env and restore after the test.
			originalEnv := map[string]*string{}
			for k, v := range tt.envOverrides {
				orig, ok := os.LookupEnv(k)
				if ok {
					originalEnv[k] = &orig
				} else {
					originalEnv[k] = nil
				}
				os.Setenv(k, v)
				// Ensure we clean up after the sub‑test
				defer func(key string) {
					if valPtr, ok := originalEnv[key]; ok && valPtr != nil {
						os.Setenv(key, *valPtr)
					} else {
						os.Unsetenv(key)
					}
				}(k)
			}
			// Unset any env vars that are not listed (they may have been set
			// globally in the test runner). This guarantees a clean slate.
			for _, key := range []string{"APP_PORT", "APP_DATABASE_URL", "APP_LOG_LEVEL"} {
				if _, listed := tt.envOverrides[key]; !listed {
					if _, had := os.LookupEnv(key); had {
						orig, _ := os.LookupEnv(key)
						originalEnv[key] = &orig
						os.Unsetenv(key)
						defer func(k string, v *string) {
							if v != nil {
								os.Setenv(k, *v)
							}
						}(key, originalEnv[key])
					}
				}
			}

			// -------------------------------------------------
			// 3️⃣ Call LoadConfig
			// -------------------------------------------------
			got, err := LoadConfig(cfgPath)

			// -------------------------------------------------
			// 4️⃣ Assertions
			// -------------------------------------------------
			if tt.wantErr {
				if err == nil {
					t.Fatalf("expected error but got none")
				}
				// If the test wants a specific sentinel, verify it.
				if tt.wantErrIs != nil && !errors.Is(err, tt.wantErrIs) {
					t.Fatalf("expected error to be %v, got %v", tt.wantErrIs, err)
				}
				// If we also want to check the validation message, look for it.
				if tt.validateErr != "" && !strings.Contains(err.Error(), tt.validateErr) {
					t.Fatalf("expected error to contain %q, got %v", tt.validateErr, err)
				}
				// Nothing more to check for error cases.
				return
			}
			if err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
			if got == nil {
				t.Fatalf("got nil config without error")
			}
			// Deep compare the struct (ignore zero‑value fields that were not set)
			if diff := cmp.Diff(tt.want, *got); diff != "" {
				t.Fatalf("config mismatch (-want +got):\n%s", diff)
			}
		})
	}
}
```

### What the test covers

| Scenario | What it verifies |
|----------|------------------|
| **Happy path (no env)** | JSON is parsed correctly and matches the struct. |
| **Port override** | Integer env var replaces the JSON value. |
| **Multiple overrides** | Several env vars are applied together. |
| **Malformed JSON** | `LoadConfig` returns an error from the decoder. |
| **Missing required field** | Validation catches an empty `DatabaseURL` and returns `ErrInvalidConfig`. |
| **Port out of range** | Validation error for illegal port numbers. |
| **Non‑numeric env var for port** | The conversion fails → original JSON value stays unchanged. |
| **Invalid log‑level via env** | Validation catches an unsupported enum value. |

### Dependencies

* `github.com/google/go-cmp/cmp` – for a nice diff in the success case.  
  Add it to your module (if not already present) with:

```bash
go get github.com/google/go-cmp/cmp
```

* Standard library only otherwise (`testing`, `os`, `encoding/json`, `strconv`, `strings`, `errors`, `path/filepath`).

### Running the test

```bash
go test ./config -v
```

All sub‑tests should pass, confirming that `LoadConfig` correctly reads JSON, applies environment‑variable overrides, validates the final configuration, and returns well‑structured errors.
